// Unit tests for the Daevanion optimizer and value model, on the real board data (web/public/daevanion.json).
import { describe, expect, it } from 'vitest'
import { DEF_UI, G, setU } from '@/core/state'
import { buildGraph, connected, optimize, setValue, type Graph } from '@/features/daevanion/optimize'
import { CLASS_DEF, defaultBps, defaultTier, skillCurve, statUnits, type DaeData } from '@/features/daevanion/values'
import { advice, parseLive, parseSkills, planPool, poolSlots, skillBases } from '@/features/daevanion/daevanion'

setU(structuredClone(DEF_UI))
// generated by tools/fetch_daevanion.py (not in git): the data tests skip without it
const file = Object.values(import.meta.glob('../public/daevanion.json', { eager: true, import: 'default' }))[0] as DaeData | undefined
const has = !!file
const D = file as DaeData

/** Every connected node set containing the starts, by brute force (tiny graphs only). */
function bruteBest(g: Graph, budget: number) {
  let best = 0
  const n = g.nodes.length
  for (let m = 0; m < 1 << n; m++) {
    const s = new Set<number>()
    for (let i = 0; i < n; i++) if (m & (1 << i)) s.add(i)
    if (!g.starts.every(x => s.has(x)) || !connected(g, s)) continue
    let c = 0
    for (const i of s) c += g.nodes[i].cost
    const v = setValue(g, s)
    if (c <= budget && v > best) best = v
  }
  return best
}

describe('Daevanion optimizer', () => {
  // S . A          start in the middle row; the valuable node B sits behind a worthless, expensive gate
  // x G B
  // C . .
  const tiny = buildGraph([{ b: 1, nodes: [
    { r: 0, c: 0, cost: 0, v: 0, start: true }, { r: 0, c: 2, cost: 1, v: 1 }, { r: 0, c: 1, cost: 1, v: 0.2 },
    { r: 1, c: 0, cost: 1, v: 0.1 }, { r: 1, c: 1, cost: 3, v: 0 }, { r: 1, c: 2, cost: 2, v: 9 }, { r: 2, c: 0, cost: 1, v: 1.5 },
  ] }])

  it('matches brute force on a small board for every budget', () => {
    for (let b = 0; b <= 9; b++) {
      const p = optimize(tiny, b)
      expect(p.spent).toBeLessThanOrEqual(b)
      expect(connected(tiny, p.owned)).toBe(true)
      expect(p.value).toBeCloseTo(bruteBest(tiny, b), 6)
    }
  })

  it('returns a buy order in which every node touches an owned one', () => {
    const p = optimize(tiny, 9), have = new Set(tiny.starts)
    for (const i of p.order) { expect(tiny.adj[i].some(j => have.has(j))).toBe(true); have.add(i) }
    expect(have).toEqual(p.owned)
  })

  it('buys skill nodes only up to a breakpoint (bundles), matching brute force', () => {
    // two skill nodes of one group behind the start, a stat node beside: level 10 + 2 = 12 is the only step
    const g = buildGraph([{ b: 1, nodes: [
      { r: 0, c: 0, cost: 0, v: 0, start: true }, { r: 0, c: 1, cost: 3, v: 0, grp: 0 }, { r: 0, c: 2, cost: 3, v: 0, grp: 0 },
      { r: 0, c: 3, cost: 3, v: 0, grp: 0 }, { r: 1, c: 0, cost: 1, v: 1.2 }, { r: 2, c: 0, cost: 1, v: 1.2 },
    ] }], [skillCurve(5, 10)])
    for (let b = 0; b <= 11; b++) expect(optimize(g, b).value, 'budget ' + b).toBeCloseTo(bruteBest(g, b), 6)
    const p = optimize(g, 6)
    expect([...p.owned].filter(i => g.nodes[i].grp === 0)).toHaveLength(2) // +2 = level 12, the third adds nothing
  })

  it('keeps locked nodes in "add" mode', () => {
    const locked = new Set([0, 3, 6])
    const p = optimize(tiny, 2, locked)
    for (const i of locked) expect(p.owned.has(i)).toBe(true)
    expect(p.spent).toBeLessThanOrEqual(2)
  })
})

describe.skipIf(!has)('Daevanion data and plan', () => {
  it('has all nine classes with the known board costs', () => {
    expect(Object.keys(D.classes)).toHaveLength(9)
    const cost = (cls: string, slot: string) => D.classes[cls].boards[slot].nodes.reduce((s, n) => s + n[2], 0)
    expect([1, 2, 3, 4, 6].map(s => cost('7', String(s)))).toEqual([134, 134, 134, 168, 232])
  })

  it('knows every default core skill of every class', () => {
    for (const [cls, def] of Object.entries(CLASS_DEF)) {
      const names = D.classes[cls].skills.map(s => s.en)
      for (const s of [...def.core, ...def.good || [], ...def.skip || []]) expect(names, `${D.classes[cls].en}: ${s}`).toContain(s)
      for (const k of Object.keys(def.mult || {})) expect(D.stats.map(x => x.key), k).toContain(k)
    }
    const cleric = D.classes['7'].skills.find(s => s.en === 'Healing Light')!
    expect(defaultTier('7', cleric)).toBe(3)
    expect(defaultTier('2', D.classes['2'].skills.find(s => s.en === 'Flash Rampage')!)).toBe(0)
    // wakayashi.gg guides: Daevanion picks = core, rest of the skill setup = good, Lv 8 filler + Defiance = skip
    expect(defaultTier('1', D.classes['1'].skills.find(s => s.en === 'Keen Strike')!)).toBe(3)
    expect(defaultTier('1', D.classes['1'].skills.find(s => s.en === 'Leaping Slam')!)).toBe(2)
    expect(defaultTier('1', D.classes['1'].skills.find(s => s.en === 'Defiance')!)).toBe(0)
  })

  it('combat speed is the best stat node, the shared damage boost bucket the weakest offensive corner', () => {
    const u = statUnits(D, '1'), v = (k: string) => u[D.stats.findIndex(s => s.key === k)] * 1.5
    expect(v('Combat Speed')).toBeGreaterThan(Math.max(...['Cooldown Reduction', 'Multi-hit Chance', 'Critical Damage Boost', 'Damage Boost', 'Damage Tolerance'].map(v)))
    expect(v('Damage Boost')).toBeLessThan(v('Critical Damage Boost'))
    expect(v('PvE Damage Boost')).toBe(v('Damage Boost'))
  })

  it('values a Common node of every stat as 1', () => {
    const u = statUnits(D, '7'), i = D.stats.findIndex(s => s.key === 'Defense Bonus'), a = D.stats.findIndex(s => s.key === 'Attack Bonus')
    expect(u[i] * 30).toBeCloseTo(1)
    expect(u[a] * 3).toBeCloseTo(1)
  })

  it('spends within budget, stays connected and gains with more points', () => {
    let last = -1
    for (const free of [0, 30, 120, 300]) {
      const p = planPool(D, '7', 'pve', 'respec', free, undefined)
      expect(p.plan.spent).toBeLessThanOrEqual(free)
      expect(connected(p.g, p.plan.owned)).toBe(true)
      expect(p.plan.value).toBeGreaterThanOrEqual(last)
      last = p.plan.value
    }
  })

  it('fills everything worth something when points are unlimited', () => {
    const p = planPool(D, '1', 'pve', 'respec', 5000, undefined)
    const all = new Set(p.g.nodes.map((_, i) => i).filter(i => p.g.nodes[i].v > 0 || p.g.nodes[i].grp >= 0 || p.g.starts.includes(i)))
    expect(p.plan.value).toBeCloseTo(setValue(p.g, all), 6)
  })

  it('skill breakpoints: only the levels that reach 8 / 12 / 16 / 20 count', () => {
    const f = skillCurve(5, 10)
    expect([0, 1, 2, 3, 4].map(f)).toEqual([0, 0, 20, 20, 20])
    expect([0, 1, 2, 3, 4].map(skillCurve(5, 12))).toEqual([0, 0, 0, 0, 20])
    expect(skillCurve(5, 7, [8, 20])(4)).toBe(20) // only the chosen breakpoints
    expect(skillCurve(5, null)(2)).toBe(20) // unknown level: assumed 10
    expect([0, 1, 2].map(skillCurve(3, 12, []))).toEqual([0, 3, 6]) // no breakpoints: every level
  })

  it('skill level without Daevanion = website level minus the open skill nodes', () => {
    const c = D.classes['7'], si = c.skills.findIndex(s => s.en === 'Bolt')
    const open: Record<string, number[]> = {}
    for (const [slot, b] of Object.entries(c.boards)) for (const n of b.nodes) if (n[3] === 2 && n[4] === si) (open[slot] ||= []).push(n[0] * 32 + n[1])
    const skills = parseSkills({ skill: { skillList: [{ category: 'Active', name: 'Bolt', skillLevel: 14 }, { category: 'Dp', name: 'X', skillLevel: 3 }] } })
    expect(skills).toEqual({ Bolt: 14 })
    const bases = skillBases(c, { at: 1, cls: '7', level: 45, open, skills }, { off: 0.5, mult: {}, tiers: {} })
    expect(bases[si]).toBe(10)
    expect(bases[(si + 1) % c.skills.length]).toBeNull()
  })

  it('Ariel: own pool, same board for every class; active skills break at their specialization levels', () => {
    expect(poolSlots(D.classes['7'], 'ariel', 45)).toEqual(['5'])
    expect(D.classes['7'].boards['5'].nodes.reduce((n, x) => n + x[2], 0)).toBe(232)
    const p = planPool(D, '2', 'ariel', 'respec', 100, undefined)
    expect(p.plan.spent).toBeLessThanOrEqual(100)
    expect(p.plan.spent).toBeGreaterThan(90)
    const keen = D.classes['1'].skills.find(s => s.en === 'Keen Strike')!
    expect(defaultBps(keen)).toEqual([8, 12, 16])
    expect(defaultBps(D.classes['1'].skills.find(s => !s.active)!)).toEqual([]) // passives: every level counts
    expect(defaultBps(D.classes['9'].skills.find(s => s.active)!)).toEqual([8, 12, 16, 20]) // no game data (Brawler)
  })

  it('attack-heavy weights buy more attack than defense-heavy ones', () => {
    const s = (U: number) => {
      setU({ ...structuredClone(DEF_UI), dae: { off: { 1: U } } })
      const p = planPool(D, '1', 'pve', 'respec', 80, undefined)
      let atk = 0, def = 0
      for (const i of p.plan.owned) {
        const n = p.refs[i].n
        if (n[3] !== 1) continue
        for (const [st] of n[4] as [number, number][]) { if (D.stats[st].key === 'Attack Bonus') atk++; if (D.stats[st].key === 'Defense Bonus') def++ }
      }
      return atk - def
    }
    expect(s(0.95)).toBeGreaterThan(s(0.05))
    setU(structuredClone(DEF_UI))
  })

  it('respec is never worse than adding to the current board with the same points', () => {
    // a "current board" bought by a defense build, then re-planned for an attack build
    setU({ ...structuredClone(DEF_UI), dae: { off: { 7: 0.05 } } })
    const old = planPool(D, '7', 'pve', 'respec', 100, undefined)
    const open: Record<string, number[]> = {}
    for (const i of old.plan.owned) { const r = old.refs[i]; if (r.n[3]) (open[r.slot] ||= []).push(r.n[0] * 32 + r.n[1]) }
    const l = { at: 1, cls: '7', level: 45, open }
    setU({ ...structuredClone(DEF_UI), dae: { off: { 7: 0.95 } } })
    const total = old.plan.spent + 20, add = planPool(D, '7', 'pve', 'add', total, l), re = planPool(D, '7', 'pve', 'respec', total, l)
    expect(re.spentNow).toBe(old.plan.spent)
    expect(add.budget).toBe(20) // only the free points
    expect(re.budget).toBe(total) // everything
    expect(planPool(D, '7', 'pve', 'respec', 0, l).budget).toBe(old.plan.spent) // nothing entered: the spent points
    expect(re.plan.value).toBeGreaterThanOrEqual(add.plan.value - 1e-6)
    for (const i of add.cur) expect(add.plan.owned.has(i)).toBe(true)
    setU(structuredClone(DEF_UI))
  })

  it('a tank with 416 points takes every combat speed, cooldown and crit damage corner', () => {
    const p = planPool(D, '2', 'pve', 'respec', 416, undefined)
    const want = ['Combat Speed', 'Cooldown Reduction', 'Critical Damage Boost'].map(k => D.stats.findIndex(s => s.key === k))
    for (const st of want) {
      const corners = p.refs.map((r, i) => [r, i] as const).filter(([r]) => r.n[3] === 1 && (r.n[4] as [number, number][]).some(([x]) => x === st))
      expect(corners.length).toBeGreaterThan(0)
      for (const [, i] of corners) expect(p.plan.owned.has(i), D.stats[st].key).toBe(true)
    }
  })

  it('recommends resetting skill levels above their last breakpoint', () => {
    // Cleric with all four Bolt nodes and Bolt at 15 on the website: 11 without Daevanion, 12 is the last breakpoint
    const c = D.classes['7'], si = c.skills.findIndex(s => s.en === 'Bolt'), open: Record<string, number[]> = {}
    for (const [slot, b] of Object.entries(c.boards)) for (const n of b.nodes) if (n[3] === 2 && n[4] === si) (open[slot] ||= []).push(n[0] * 32 + n[1])
    G.dae = D
    setU({ ...structuredClone(DEF_UI), dae: { free: 0 }, daeLive: { Standard: { at: 1, cls: '7', level: 45, open, skills: { Bolt: 15 } } } })
    const [pve] = advice()
    expect(pve.pool).toBe('pve')
    expect(pve.waste).toEqual([{ si, level: 15, top: 12, extra: 3, points: 9 }])
    expect(pve.respec).toBeGreaterThanOrEqual(pve.add - 1e-6)
    G.dae = undefined
    setU(structuredClone(DEF_UI))
  })

  it('MP is only bought on the way to other nodes', () => {
    const p = planPool(D, '7', 'pve', 'respec', 120, undefined), mp = D.stats.findIndex(s => s.key === 'MP')
    for (const i of p.plan.owned) {
      const n = p.refs[i].n
      if (n[3] !== 1 || !(n[4] as [number, number][]).some(([x]) => x === mp)) continue
      // an MP node in the plan must lead somewhere: another owned node beyond it
      expect(p.g.adj[i].filter(j => p.plan.owned.has(j)).length, 'MP node is a dead end').toBeGreaterThan(1)
    }
  })

  it('leaves out boards above the character level', () => {
    expect(poolSlots(D.classes['7'], 'pve', 25)).toEqual(['1', '2'])
    expect(poolSlots(D.classes['7'], 'pvp', 44)).toEqual([])
  })
})

describe('Daevanion website boards', () => {
  it('reads class, level and open nodes', () => {
    const info = { profile: { characterLevel: 45 }, daevanion: { boardList: [{ id: 71, open: 1, openNodeCount: 1 }, { id: 76, open: 1, openNodeCount: 0 }] } }
    const b71 = { nodeList: [{ row: 8, col: 8, type: 'Start', open: 1 }, { row: 7, col: 8, type: 'Stat', open: 1 }, { row: 9, col: 8, type: 'Stat', open: 0 }] }
    expect(parseLive(info, { 71: b71 }, 5)).toEqual({ at: 5, cls: '7', level: 45, open: { 1: [7 * 32 + 8], 6: [] } })
    expect(parseLive({ daevanion: { boardList: null } }, {})).toBeNull()
  })
})
